CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(order_id TEXT PRIMARY KEY,user_id BIGINT REFERENCES users(id),request_json TEXT NOT NULL,bill_json TEXT NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT now());
CREATE TABLE IF NOT EXISTS payments(id BIGSERIAL PRIMARY KEY,order_id TEXT UNIQUE REFERENCES orders(order_id),user_id BIGINT REFERENCES users(id),razorpay_order_id TEXT UNIQUE NOT NULL,razorpay_payment_id TEXT,amount_paise BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'CREATED',created_at TIMESTAMP WITH TIME ZONE DEFAULT now());

ALTER TABLE orders ADD COLUMN IF NOT EXISTS idempotency_key TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS payment_method TEXT NOT NULL DEFAULT 'UPI';
CREATE UNIQUE INDEX IF NOT EXISTS orders_retry ON orders(user_id,idempotency_key);
